'use strict';
// Champion records are built from content/champions by champions.py.
const MATCHUPS=[
 {slug:'ahri-vs-lux',title:'Ahri vs Lux',kind:'Mid lane study',champions:['ahri','lux'],summary:'Study commitment, spacing and safe follow-up.',focus:'Watch how a move forward changes both players’ options. This exercise compares mobility decisions with the risk of stepping into attack range.',sides:[['Playing Ahri','Before moving forward, identify how you will leave if the attempt fails. Reassess after Lux uses a spell rather than assuming any missed spell makes the whole lane safe.'],['Playing Lux','After a spell hits, check whether stepping forward to attack would expose you to a response. Keep the space you need to retreat instead of chasing every mark.']],scenario:'Hypothetical: Lux lands a spell while Ahri still has mobility available. Lux can stay at range or walk forward for an attack. Pause and compare the reward with the route Ahri could use to respond. The answer changes with health, wave position and nearby players.',drill:'Review three exchanges. Write down who moved forward first, which tools remained available, and whether that player had an exit.',lessons:['spacing','cooldown-tracking','trading']},
 {slug:'garen-vs-darius',title:'Garen vs Darius',kind:'Top lane study',champions:['garen','darius'],summary:'Study trade length, bleed stacks and recovery.',focus:'Darius’s stacking bleed makes continued contact matter. Garen’s recovery rewards finding a break from incoming damage. Use these mechanics to examine when a trade should end.',sides:[['Playing Garen','Plan where to leave before trading. If Darius can keep contact, reassess early rather than waiting until your health forces the decision. A recovery plan requires a real break from damage.'],['Playing Darius','Watch whether you can extend contact safely. Do not chase solely because stacks are building: the wave, enemy tower and missing players can make continuing a poor choice.']],scenario:'Hypothetical: Garen steps up for a minion and Darius responds. The trade continues toward Darius’s side of the lane. Pause before Garen moves farther forward: where can he leave, what stacks are visible, and who else could arrive?',drill:'Review three trades. Note visible stacks, the direction each player moved, and when each had a chance to disengage. Judge the decision using what was visible then.',lessons:['trading','spacing','wave-management']},
 {"slug": "kogmaw-vs-ashe", "title": "Kog'Maw vs Ashe", "kind": "Bot lane study", "champions": ["kogmaw", "ashe"], "summary": "Study a lane of slows where neither carry can escape.", "focus": "Ashe’s attacks slow, her base range is longer than Kog’Maw’s, and Enchanted Crystal Arrow can stun him from far away. Neither champion has a dash, so neither escapes easily; spacing and which support is closer decide most fights.", "sides": [["Playing Kog'Maw", "Before stepping up, ask where Enchanted Crystal Arrow could come from, especially when her support is ready to follow it. Trade with Barrage active, when your range is longer than hers. With no dash on either side, the player whose support is closer usually wins the exchange."], ["Playing Ashe", "Use range and slows to trade when Kog’Maw’s Barrage is down. Keep Volley for when he steps out from behind his minions. Save Enchanted Crystal Arrow for a target your team can follow up on."]], "scenario": "Hypothetical: Ashe has Enchanted Crystal Arrow ready and her support waits in the brush. Kog’Maw has used Barrage and is pushing the wave. Pause: what does staying to finish the wave risk?", "drill": "Review three exchanges. Mark who had the longer range at that moment and whose support was closer.", "lessons": ["spacing", "crowd-control", "warding"], "phases": [["Early lane", "Her slows let her win long trades early. Avoid long trades without Barrage."], ["Mid game", "Hawkshot reveals areas. Assume she can see you, and do not walk into unknown brush."], ["Teamfights", "Enchanted Crystal Arrow can start fights. Stay behind your frontline so it hits them first."]], "tips": ["Hawkshot reveals the area it flies over. Expect her to know where you are.", "Ranger's Focus speeds her attacks for a short time. Step back when it is active.", "Enchanted Crystal Arrow stuns longer the farther it flies. A long-range arrow is especially dangerous.", "You both lack dashes, so whichever support lands control first usually wins."]},
 {"slug": "kogmaw-vs-caitlyn", "title": "Kog'Maw vs Caitlyn", "kind": "Bot lane study", "champions": ["kogmaw", "caitlyn"], "summary": "Study surviving a range disadvantage until Bio-Arcane Barrage narrows it.", "focus": "Caitlyn’s base attack range is longer than Kog’Maw’s, so she can hit him while he farms without being hit back. Yordle Snap Trap and 90 Caliber Net make every step toward the wave cost something. This study is about which minions are worth that cost, and how Bio-Arcane Barrage changes the spacing as it ranks up.", "sides": [["Playing Kog'Maw", "Give up last hits that require walking into her range while Bio-Arcane Barrage is down; take them from the far side of the wave or let them go. Activate Barrage when Caitlyn steps forward for a minion, so the extra range answers her trade instead of running out while she stands back. Walk around traps rather than through them, especially near your tower where a trapped Kog’Maw can be dived."], ["Playing Caitlyn", "Your lane advantage is range. Hit Kog’Maw whenever he steps up for a minion, and step back when Bio-Arcane Barrage starts. Place traps where he must walk to reach the wave or to leave a fight. Keep 90 Caliber Net for his support’s engage or for when he chases with Barrage active, rather than spending it on a small trade."]], "scenario": "Hypothetical: Kog’Maw is low on mana and has just used Bio-Arcane Barrage to contest a cannon minion. Caitlyn has a trap beside the wave and Net available. Pause: should Kog’Maw stay for the next minion, and should Caitlyn step forward now that Barrage is ending?", "drill": "Review three minutes of lane. Mark each time Kog’Maw used Bio-Arcane Barrage and whether Caitlyn was in his range when it started. Note how much health each contested last hit cost.", "lessons": ["spacing", "last-hitting", "cooldown-tracking"], "phases": [["Early lane", "Expect to give up some farm. Her longer range and Headshot let her win most early trades, so protect your health first and last-hit what you can safely reach. Keep the wave near your tower if you can; a long lane gives her more free shots."], ["Mid game", "As Barrage ranks up and your items arrive, the range gap closes. Caitlyn wants to take towers early behind a wall of traps. Group with your team rather than defending a side tower alone against her siege."], ["Teamfights", "She will trap the ground in front of her team and Net away when you reach her. Move forward once her traps are visible or triggered, attack the nearest safe target, and use Living Artillery on her if she stays behind her frontline."]], "tips": ["Headshot charges faster while she stands in brush; take extra care when she has been waiting in a bush.", "Traps are visible once placed. Note where they are before you walk forward, not after.", "When she uses 90 Caliber Net to leave, her escape is on cooldown. That is the safest time for your support to engage.", "Living Artillery deals more damage to low-health targets, so it can finish her from beyond her range.", "Supports who can engage on her or heal you through poke make this lane much easier."]},
 {"slug": "kogmaw-vs-draven", "title": "Kog'Maw vs Draven", "kind": "Bot lane study", "champions": ["kogmaw", "draven"], "summary": "Study refusing early all-ins against a lane that snowballs.", "focus": "Draven’s caught axes give him heavy early damage, and Stand Aside can knock Kog’Maw away just as he begins attacking. Kog’Maw does not want a long early fight. The axes also show where Draven plans to move, which lets both players predict the next exchange.", "sides": [["Playing Kog'Maw", "Watch where each axe will land: catching it moves Draven to a predictable spot, sometimes inside your range and your support’s. Concede contested minions in the early levels instead of starting a long fight, and keep the wave near your tower when you can. Use Void Ooze when he walks forward to catch an axe, and save Living Artillery to finish a low target who is running."], ["Playing Draven", "Your early damage is the lead. Trade when Kog’Maw steps up and your axes are spinning. Throw axes where catching them keeps you safe, not where the catch walks you into his slow and his support. Dying resets the adoration you have built, so do not force a tower dive just because Kog’Maw is low."]], "scenario": "Hypothetical: Draven has two axes spinning and Kog’Maw walks forward for a melee minion. One axe will land on Draven’s side of the wave and one closer to Kog’Maw. Pause: should Draven catch both, and what should Kog’Maw do if he tries?", "drill": "Review three Draven trades. Note where each axe landed and whether catching it moved Draven toward danger. Record whether you stayed for the minion or let it go.", "lessons": ["trading", "all-ins", "freezing"], "phases": [["Early lane", "The first few levels are his strongest window. Let minions go when taking them means a long fight, and avoid trading while he has two axes spinning. Staying alive matters more than a few minions here."], ["Mid game", "If Draven is ahead, he will look for fights in the river. Move with your team and avoid walking into unwarded brush. If he is behind, his damage drops quickly, and you can fight him more evenly."], ["Teamfights", "Draven has to keep moving to catch axes. Use Void Ooze on the ground between him and his next axe, and focus him when he steps forward to catch one."]], "tips": ["Make him choose: if catching an axe means walking into your range, he either takes damage or gives up the axe.", "Stand Aside knocks you away. Save Barrage until after he has used it.", "Whirling Death flies out and comes back, so it can hit you twice. Move out of its path both ways.", "Killing you gives him bonus gold from League of Draven, so an early death costs you more than usual."]},
 {"slug": "kogmaw-vs-ezreal", "title": "Kog'Maw vs Ezreal", "kind": "Bot lane study", "champions": ["kogmaw", "ezreal"], "summary": "Study absorbing safe poke without chasing.", "focus": "Ezreal pokes with Mystic Shot from range and uses Arcane Shift to leave almost any fight. Kog’Maw cannot catch him, and Ezreal rarely needs to commit. Neither player usually wins this lane outright, so the study is about health and farm over time.", "sides": [["Playing Kog'Maw", "Stand behind minions so Mystic Shot is blocked, and accept that you will rarely kill a careful Ezreal in lane. Keep Bio-Arcane Barrage for when he walks forward to attack or uses Arcane Shift aggressively. Your goal is to reach your item spikes with full farm; chasing him after his blink costs you the wave."], ["Playing Ezreal", "Poke from angles where minions do not block Mystic Shot, and treat Arcane Shift as your escape rather than your engage. Do not stand within Kog’Maw’s attack range while Barrage is active. Use your safe lane to take plates and early objectives before longer fights favor him."]], "scenario": "Hypothetical: Ezreal uses Arcane Shift forward to finish Kog’Maw’s wounded support. Kog’Maw has Bio-Arcane Barrage and Void Ooze ready. Pause: is Ezreal now reachable, and is this the exchange Kog’Maw has been waiting for?", "drill": "Review three minutes of lane. Count how many Mystic Shots hit you and where you stood when they did. Mark each Arcane Shift and whether you could have punished it.", "lessons": ["dodging", "poking", "power-spikes"], "phases": [["Early lane", "Farm safely and dodge Mystic Shot. Neither of you wants an early all-in, so your supports usually decide who controls the lane."], ["Mid game", "Ezreal gets stronger sooner. Avoid long fights while you are short of items, and take safe waves instead."], ["Teamfights", "Ezreal pokes from the back and stays safe. Hit whoever is closest; chasing him through his team is rarely worth it."]], "tips": ["Each Mystic Shot that hits lowers his other cooldowns, so dodging it slows his whole kit.", "Trueshot Barrage has long range. Expect it when you are low, even far away.", "Arcane Shift can go over walls. Do not chase him into fog.", "Essence Flux marks you for extra damage from his next attack or spell."]},
 {"slug": "kogmaw-vs-jhin", "title": "Kog'Maw vs Jhin", "kind": "Bot lane study", "champions": ["kogmaw", "jhin"], "summary": "Study reload windows and a root that follows damage.", "focus": "Jhin fires four shots, then must reload; the fourth shot deals extra damage. Deadly Flourish roots only a champion recently damaged by Jhin or his allies. Kog’Maw’s best trades come during Jhin’s reload.", "sides": [["Playing Kog'Maw", "Trade while Jhin is reloading, because he cannot attack back. After taking damage, avoid standing in a line from him, since Deadly Flourish can now root you. Avoid unwarded brush where Captive Audience traps may be hidden."], ["Playing Jhin", "Pressure Kog’Maw with your fourth shot, then reposition during the reload. Fire Deadly Flourish after you or your support have damaged him. Use Curtain Call to finish a slow, immobile target from range."]], "scenario": "Hypothetical: Jhin hits Kog’Maw with his fourth shot and starts reloading. Kog’Maw has Barrage ready. Pause: is this the moment to trade back, and how long does the window last?", "drill": "Review three trades. Mark each Jhin reload and whether you traded during it.", "lessons": ["cooldown-tracking", "trading", "dodging"], "phases": [["Early lane", "Jhin’s fourth shot hits hard, and he cannot attack while reloading. Step back when the fourth shot is loaded, and trade with Barrage as soon as he starts reloading."], ["Mid game", "Deadly Flourish has very long range and roots anyone recently hit by Jhin or his allies. After taking poke in the mid game, avoid walking through fog where it could come from."], ["Teamfights", "Curtain Call fires from far behind his team. Keep a teammate in front of you, and move out of its cone if you are low; you cannot dash out of the later shots."]], "tips": ["His fourth shot always crits. Do not trade into it.", "Captive Audience traps reveal and slow you. Ward or sweep brush before walking into it.", "Each Curtain Call shot stops on the first champion it hits, so an ally in front of you can absorb it.", "Jhin gains movement speed when he crits, so he can often walk away after his fourth shot. Do not chase him past your support."]},
 {"slug": "kogmaw-vs-jinx", "title": "Kog'Maw vs Jinx", "kind": "Bot lane study", "champions": ["kogmaw", "jinx"], "summary": "Study a scaling mirror where range decides the trades.", "focus": "Both champions grow stronger with items and want long fights later. Jinx’s rocket form gives her extra range, and Zap! with Flame Chompers! can root Kog’Maw, who has no dash. Bio-Arcane Barrage lets Kog’Maw reach further than her minigun, so the form she is in decides who can trade.", "sides": [["Playing Kog'Maw", "Note where Flame Chompers! land and never walk across them to reach a minion. Zap! travels in a line: stay behind minions or move sideways when she aims it. Trade when she is in minigun form for farming, because her range is shorter then."], ["Playing Jinx", "Use rocket form to hit Kog’Maw when he steps up, and place Flame Chompers! on his retreat path; he cannot dash over them. Avoid long exchanges during his Barrage window. In teamfights, hit the closest safe target first; a takedown gives you movement speed to stay out of his range."]], "scenario": "Hypothetical: Jinx places Flame Chompers! between Kog’Maw and his tower, then aims Zap!. Kog’Maw has Bio-Arcane Barrage ready and his support is beside him. Pause: should Kog’Maw fight now, or walk away from the chompers first?", "drill": "Review three exchanges. Note whether Jinx was in rocket or minigun form, and whether you had the range advantage at that moment.", "lessons": ["spacing", "skillshots", "power-spikes"], "phases": [["Early lane", "Early trades are mostly about rocket poke. Stay behind minions so rockets also hit them, and trade back with Barrage when she switches to minigun."], ["Mid game", "You both scale. Avoid risky skirmishes; whoever keeps farming fully usually wins later."], ["Teamfights", "Jinx gets faster after takedowns. Damage her early in the fight, or stay safe until she runs out of reach."]], "tips": ["Rockets deal area damage. Standing next to the minions she is hitting also hurts you.", "Super Mega Death Rocket! does more damage to low targets. Stay healthy when she has it.", "Flame Chompers! take a moment to arm; step away before they do.", "Get Excited! gives her speed after takedowns, so the first kill in a fight matters most."]},
 {"slug": "kogmaw-vs-kaisa", "title": "Kog'Maw vs Kai’Sa", "kind": "Bot lane study", "champions": ["kogmaw", "kaisa"], "summary": "Study plasma marks and the dive that follows them.", "focus": "Kai’Sa applies plasma with her attacks and Void Seeker, and Killer Instinct lets her dash to a marked enemy from long range. Kog’Maw cannot dash away, so being marked is a real danger once she has her ultimate. Early, Icathian Rain punishes Kog’Maw for standing away from minions.", "sides": [["Playing Kog'Maw", "Stay near minions so Icathian Rain spreads its missiles, and sidestep Void Seeker because it marks you. Once Kai’Sa has Killer Instinct, a plasma hit means she can land beside you; keep your support close before you take a trade. When she lands, use Void Ooze and fight back: she has to come into your range to hit you."], ["Playing Kai’Sa", "Hit Kog’Maw with Void Seeker to mark him for Killer Instinct. Use Icathian Rain when he walks away from his minions. Dive only when his support and slow are unavailable; at close range with Barrage active, Kog’Maw can win a straight fight."]], "scenario": "Hypothetical: Kai’Sa hits Kog’Maw with Void Seeker. She has Killer Instinct ready and Kog’Maw’s support is a few steps behind him. Pause: where should Kog’Maw move in the next second?", "drill": "Review three Kai’Sa engages. Note how she applied plasma, where she landed, and whether you were beside your support at the time.", "lessons": ["dodging", "positioning", "peeling"], "phases": [["Early lane", "Kai’Sa is weaker before her ability upgrades. Trade back when she steps up without minions around her."], ["Mid game", "Once she has Killer Instinct, keep your team close; she looks for a marked target."], ["Teamfights", "She needs to mark you first. Stand behind your frontline so Void Seeker hits them, not you."]], "tips": ["Void Seeker stops on the first enemy it hits. Keep allies or minions between you and her.", "Supercharge can make her invisible after its upgrade; watch for where she disappears.", "Killer Instinct gives her a shield. Save Void Ooze and burst for after it fades.", "Icathian Rain spreads its missiles over nearby minions, so stay close to yours."]},
 {"slug": "kogmaw-vs-kalista", "title": "Kog'Maw vs Kalista", "kind": "Bot lane study", "champions": ["kogmaw", "kalista"], "summary": "Study short hops and stacking spears.", "focus": "Kalista hops after each attack, and every spear in a target adds to Rend damage. Her early pressure is strong, but she must stay close to hit. Kog’Maw can trade with Barrage active, but should not let spears stack over a long fight.", "sides": [["Playing Kog'Maw", "Trade only if you can leave before Rend stacks get high. Use Void Ooze to slow her hops. When Kalista has Fate’s Call, her support can be thrown at you, so keep extra space."], ["Playing Kalista", "Stack Rend with short trades, then use it to finish. Stay out of his range during Barrage. Use Fate’s Call with your support to engage on him."]], "scenario": "Hypothetical: Kalista has hit Kog’Maw with several spears. Kog’Maw has Barrage ready, and the wave is near his tower. Pause: should Kog’Maw trade now or step out of range?", "drill": "Review three Kalista trades. Count the spears on you before Rend and note when you left.", "lessons": ["trading", "disengaging", "cooldown-tracking"], "phases": [["Early lane", "Kalista is strongest in the first few levels. Respect her early trades, stay near your support, and do not stay in long fights while her spears build up."], ["Mid game", "Her early lead matters most to her. If you survive the lane without falling behind, the later fights become much more even."], ["Teamfights", "Kalista needs to keep attacking to move with her hops. Slow her with Void Ooze, and focus her when she has to step forward."]], "tips": ["Rend damages every target with spears in it. Leave her range once spears stack.", "Sentinel scouts the map. Assume she can see you moving through the river.", "Fate's Call can throw her support at you. Keep extra distance when she has it.", "Her hops happen after attacks. Slowing her or walking out of her range breaks the pattern."]},
 {"slug": "kogmaw-vs-lucian", "title": "Kog'Maw vs Lucian", "kind": "Bot lane study", "champions": ["kogmaw", "lucian"], "summary": "Study short burst trades against a dash.", "focus": "Lucian trades in short bursts: a dash, a few double shots and a retreat. Kog’Maw cannot follow a dash and loses most short exchanges early. The question is how Kog’Maw can make each burst cost Lucian something, and how long Lucian can keep that pressure before Kog’Maw’s items arrive.", "sides": [["Playing Kog'Maw", "Stand where Relentless Pursuit would land Lucian inside your support’s reach, not at the edge of the wave. When he dashes in, answer with Void Ooze and attacks instead of turning to run across open ground. Once his dash is on cooldown, that is your window to trade back with Bio-Arcane Barrage."], ["Playing Lucian", "Trade when Kog’Maw steps toward the wave, then dash out before his support responds. Keep Relentless Pursuit available while Barrage is active, because that is when his attacks win a longer fight. Turn the early lead into tower damage and objectives before he completes his items."]], "scenario": "Hypothetical: Lucian dashes forward and hits Kog’Maw with Piercing Light through a minion. Kog’Maw has Bio-Arcane Barrage ready and Lucian’s dash is now on cooldown. Pause: should Kog’Maw retreat or answer now?", "drill": "Review three Lucian dashes. Record whether Relentless Pursuit was used to engage or to leave, and whether you traded back while it was on cooldown.", "lessons": ["cooldown-tracking", "trading", "spacing"], "phases": [["Early lane", "Lucian wins short trades early. Farm near your support, keep the wave from pushing toward his side, and do not fight him while his dash is ready and your support is away."], ["Mid game", "He wants mid-game fights before your items are finished. Do not take side lanes alone; stay with your frontline so they can absorb his dash."], ["Teamfights", "He enters with Relentless Pursuit. Stand behind a teammate who can stop him, and keep Void Ooze ready for where he lands."]], "tips": ["Piercing Light goes through minions. Do not stand in line behind a minion he can target.", "Ardent Blaze marks you, and if Lucian hits you while marked he gains speed to chase. Step back when it lands.", "The Culling fires in a line. Step to the side rather than straight back.", "Watch his dash. When it is on cooldown, you can trade back."]},
 {"slug": "kogmaw-vs-missfortune", "title": "Kog'Maw vs Miss Fortune", "kind": "Bot lane study", "champions": ["kogmaw", "missfortune"], "summary": "Study minion position against a bounce shot and a long channel.", "focus": "Double Up bounces through a minion or champion to the target behind it, so Kog’Maw’s safe spot changes as minions lose health. Bullet Time is a channel that deals heavy damage to an immobile carry. Kog’Maw cannot dash out, but he can walk out of the cone or rely on an ally to interrupt it.", "sides": [["Playing Kog'Maw", "Do not stand behind a low-health minion in line with Miss Fortune; that is where Double Up bounces. If Bullet Time starts, walk sideways out of the cone rather than straight back through it. Trade after she uses Double Up, when her burst is on cooldown."], ["Playing Miss Fortune", "Use Double Up through a dying minion when Kog’Maw stands behind it. Make It Rain slows him and sets up your support’s engage. Keep Bullet Time for when he is locked down or caught without an escape."]], "scenario": "Hypothetical: a caster minion in front of Kog’Maw is low on health. Miss Fortune walks toward it with Double Up ready. Pause: where should Kog’Maw stand to take the next last hit?", "drill": "Review three Double Up hits. Note which minion it bounced from and where you could have stood instead.", "lessons": ["positioning", "last-hitting", "dodging"], "phases": [["Early lane", "Double Up hits hard early. Trade only after it has been used."], ["Mid game", "She wants to set up Bullet Time in tight spaces. Avoid narrow areas like jungle paths when she has it."], ["Teamfights", "Bullet Time can be stopped with crowd control. Ask your team to interrupt it."]], "tips": ["Strut makes her faster when she has not been hit recently. Damaging her removes it.", "Make It Rain slows. Walk out of the zone instead of attacking inside it.", "Love Tap does more damage to new targets, so she wants to switch between you and your support.", "Living Artillery from outside her range can punish her when she channels Bullet Time."]},
 {"slug": "kogmaw-vs-samira", "title": "Kog'Maw vs Samira", "kind": "Bot lane study", "champions": ["kogmaw", "samira"], "summary": "Study a projectile block and a dash all-in.", "focus": "Blade Whirl destroys incoming projectiles, including Kog’Maw’s attacks, while it lasts. Wild Rush and Flair give Samira gap-closing and burst, and her style grade builds toward Inferno Trigger. Kog’Maw must avoid wasting his firing window into Blade Whirl.", "sides": [["Playing Kog'Maw", "Stop attacking while Blade Whirl is active, and use Void Ooze after it ends rather than during it. Respect her when her style grade is high and her support has engage ready. Start Bio-Arcane Barrage after Blade Whirl is used, not before she commits."], ["Playing Samira", "Use Blade Whirl when Kog’Maw starts his Barrage window to waste his attacks. Dash in with Wild Rush after your support lands control; you need contact to win. Build style before you dive so Inferno Trigger is ready when you reach him."]], "scenario": "Hypothetical: Samira dashes in with Wild Rush and starts Blade Whirl. Kog’Maw has Barrage ready and his support has a stun. Pause: what should Kog’Maw do in the next second?", "drill": "Review three Samira engages. Record whether you attacked into Blade Whirl and whether Barrage was still available after it ended.", "lessons": ["cooldown-tracking", "disengaging", "peeling"], "phases": [["Early lane", "With an engage support, Samira can all-in from the second or third level. Stay level with or behind your minions so her support cannot land control without walking into the wave, and do not trade while both of them have their engage ready."], ["Mid game", "Her style grade climbs with each different attack and ability she uses, and resets after she stops fighting. If she arrives at a skirmish already near her top grade, she is close to Inferno Trigger; step back until it is spent."], ["Teamfights", "Samira usually dives right after her team lands crowd control. Stand behind a teammate who can stop her, keep Void Ooze for her landing spot, and wait out Blade Whirl before you start attacking."]], "tips": ["Blade Whirl blocks your attacks, but it does not stop you from walking away. Use those seconds to reposition.", "Inferno Trigger can only be cast at her highest style grade, so a low grade means her ultimate is not available yet.", "A champion takedown resets Wild Rush, so one kill can carry her straight to the next target. Do not let a teammate die beside you.", "Ask your support to save their crowd control for her dash rather than spending it on her support."]},
 {"slug": "kogmaw-vs-tristana", "title": "Kog'Maw vs Tristana", "kind": "Bot lane study", "champions": ["kogmaw", "tristana"], "summary": "Study early jump all-ins and the knockback.", "focus": "Tristana’s Rocket Jump and Explosive Charge give her strong early all-ins, and her range grows as she levels. Buster Shot can knock Kog’Maw away just as his Barrage window begins.", "sides": [["Playing Kog'Maw", "Watch for the bomb and Rocket Jump in the first few levels, and stay close to your support. When she jumps in, use Void Ooze on her landing spot and fight back; running gives her free attacks. Track Buster Shot, because she will use it to push you out of range."], ["Playing Tristana", "All-in early, before Kog’Maw has items, and attach Explosive Charge before you jump. Use Buster Shot to knock him away from your target or into your team. A takedown can refresh Rocket Jump, but plan your exit before you rely on that."]], "scenario": "Hypothetical: both bot laners are level 2. Tristana places Explosive Charge on Kog’Maw. Pause: what should Kog’Maw do before the bomb detonates?", "drill": "Review the first three minutes. Record each Tristana jump and whether you were near your support.", "lessons": ["all-ins", "power-spikes", "trading"], "phases": [["Early lane", "Tristana’s jump with Explosive Charge is very dangerous at levels 2 and 3. Stay near your support, and do not let her bomb stack fully on you; walk away before the final hits land."], ["Mid game", "Explosive Charge also takes towers quickly. When her team groups to push, defend with your team rather than alone, because she can jump in for kills under the tower."], ["Teamfights", "Tristana jumps into fights looking for resets. Save Void Ooze for her landing, and stand behind teammates who can stop her."]], "tips": ["Explosive Charge explodes after several hits. Back away before she stacks it fully.", "Buster Shot knocks you away. Expect it when she is low or wants to push you out of a fight.", "Her range grows with her level, so later in the game she can hit you from further away.", "Rocket Jump resets on takedowns and full bomb detonations, so one kill can bring her straight back into the fight."]},
 {"slug": "kogmaw-vs-varus", "title": "Kog'Maw vs Varus", "kind": "Bot lane study", "champions": ["kogmaw", "varus"], "summary": "Study long-range poke and a root that spreads.", "focus": "Varus pokes from long range with Piercing Arrow, and Chain of Corruption roots one target and spreads to nearby allies. Kog’Maw has no dash, so standing next to his support can let one ultimate catch both of them.", "sides": [["Playing Kog'Maw", "Move sideways while Varus charges Piercing Arrow; walking straight back keeps you in its line. Do not stand beside your support when Varus has his ultimate ready. Trade after he fires the arrow, when his poke is on cooldown."], ["Playing Varus", "Charge Piercing Arrow when Kog’Maw walks up to last-hit. Use Chain of Corruption when Kog’Maw and his support stand together. Avoid long exchanges once Barrage is active."]], "scenario": "Hypothetical: Kog’Maw and his support stand side by side at the wave. Varus has Chain of Corruption ready. Pause: what should each player do?", "drill": "Review three Varus arrows. Note whether you moved sideways or straight back while the arrow was charging.", "lessons": ["dodging", "skillshots", "poking"], "phases": [["Early lane", "Varus can poke you from very long range with Piercing Arrow. Keep your health high, farm from behind your minions, and let your support decide when to engage."], ["Mid game", "In the mid game, Chain of Corruption spreads its root to nearby allies. Do not walk through jungle paths tightly grouped with your team when he has it ready."], ["Teamfights", "Stand a little apart from your teammates so one root does not catch several of you. If the chain lands on your frontline, back away from them until it has spread or ended."]], "tips": ["Hail of Arrows reduces healing for anyone standing in it. Do not rely on lifesteal or support heals inside the zone.", "Blighted Quiver stacks from his attacks make his abilities hit harder. Leave after a few attacks rather than taking a long trade.", "Varus moves more slowly while charging Piercing Arrow. That is a good moment for your support to engage on him.", "Move sideways while the arrow charges; walking straight back keeps you in its line."]},
 {"slug": "kogmaw-vs-vayne", "title": "Kog'Maw vs Vayne", "kind": "Bot lane study", "champions": ["kogmaw", "vayne"], "summary": "Study two late-game carries trying to survive the lane.", "focus": "Vayne and Kog’Maw both want to reach the late game, and both deal damage based on the target’s health. Vayne’s base range is longer than Kog’Maw’s, but Bio-Arcane Barrage reverses that while it lasts. Condemn punishes standing next to walls, and Tumble lets her dodge an engage.", "sides": [["Playing Kog'Maw", "Stay away from walls while Vayne has Condemn ready; a wall stun on a champion without a dash often decides the fight. Trade with Barrage active, when your range is longer than hers. When she Tumbles toward you, use Void Ooze and keep attacking rather than turning to run."], ["Playing Vayne", "Farm safely early and look for Condemn when Kog’Maw stands near a wall. Do not trade while Barrage is active unless Tumble can reach him; outside that window you can hit him from beyond his range. In teamfights, threaten him from the side, where his lack of an escape matters most."]], "scenario": "Hypothetical: Kog’Maw farms next to the river wall. Vayne has Condemn ready and her support moves toward the brush. Pause: what should Kog’Maw do before taking the next minion?", "drill": "Review three exchanges. Mark where you stood relative to walls and whether Barrage was active when the trade began.", "lessons": ["positioning", "spacing", "power-spikes"], "phases": [["Early lane", "Neither of you is strong early. Short trades with Barrage favor you; Vayne usually farms and waits for her ultimate."], ["Mid game", "Final Hour makes her harder to hit. Respect it while it is active, then fight back after it ends."], ["Teamfights", "Vayne needs to Tumble into range. Keep Void Ooze to slow her, and stay near your frontline."]], "tips": ["Silver Bolts deal true damage on every third hit. Step back before that third hit lands.", "Condemn needs a wall to stun. Stay in open space when it is ready.", "Final Hour makes Tumble turn her invisible. Stay near your team so she cannot reach you unseen.", "Your damage based on target health works well against her low health."]}
];
let directoryQueries={champions:'',matchups:''};
function indexMode(){return /^#\/(champions|champion)(\/|$)/.test(location.hash)?'champions':/^#\/(matchups|matchup)(\/|$)/.test(location.hash)?'matchups':'lessons';}
function searchKey(text){return text.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,'');}
function matchesGuide(a,query){const haystack=searchKey([a.title,a.id||'',a.kind,a.summary,...(a.tags||[])].join(' '));return query.trim().split(/\s+/).filter(Boolean).every(w=>haystack.includes(searchKey(w)));}
function directoryItems(){return indexMode()==='champions'?CHAMPIONS:MATCHUPS;}
function guideHref(item){return '#/'+(CHAMPIONS.includes(item)?'champion':'matchup')+'/'+item.slug;}
function guideLinks(items){return items.map(a=>`<div class="guide-card"><h2><a href="${guideHref(a)}">${esc(a.title)}</a></h2><p>${esc(a.summary)}</p></div>`).join('');}
function updateIndex(){
 const mode=indexMode(),label=mode==='champions'?'Champions':mode==='matchups'?'Matchups':'Lesson path';
 $('#lesson-index').hidden=mode!=='lessons';$('#directory-index').hidden=mode==='lessons';
 $('.browser').setAttribute('aria-label',mode==='lessons'?'Guided lesson path':label+' index');
 $('#return').textContent='← '+label;$('.status').textContent=mode==='lessons'?'One lesson at a time':'Learn through practice';
 document.querySelectorAll('[data-index]').forEach(a=>{if(a.dataset.index===mode)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});
 if(mode==='lessons')return;
 const items=directoryItems(),query=directoryQueries[mode]||'';$('#directory-search').value=query;
 $('#directory-title').textContent=label;$('#directory-intro').textContent=mode==='champions'?'All '+CHAMPIONS.length+' champions, A–Z. Search by name or teamfight style.':'Starter matchups, A–Z. Each guide covers both sides of the lane.';
 $('#directory-search').placeholder=mode==='champions'?'Find a champion':'Find either champion';
 const matches=items.filter(a=>matchesGuide(a,query));
 $('#directory-count').textContent=matches.length+' of '+items.length+' guides';$('#directory-empty').hidden=!!matches.length;
 $('#directory-links').innerHTML=matches.map(a=>`<a class="topic" href="${guideHref(a)}" ${location.hash===guideHref(a)?'aria-current="page"':''}><strong>${esc(a.title)}</strong><small>${esc(a.kind)}</small></a>`).join('');
}
function renderDirectory(state,initial){
 const mode=indexMode();if(mode==='lessons')return false;
 const items=directoryItems(),detail=location.hash.startsWith(mode==='champions'?'#/champion/':'#/matchup/'),a=items.find(a=>guideHref(a)===location.hash);
 const title=a?a.title:detail?'Guide not found':mode==='champions'?'Champion guides':'Matchup guides';
 let body='';
 if(a){
  body=`<p class="lead">${esc(a.summary)}</p>`;
  if(mode==='champions')body=a.html;
  else{const cs=a.champions.map(s=>CHAMPIONS.find(c=>c.slug===s));body=`<div class="versus">${cs.map((c,k)=>`${k?'<span class="vs" aria-hidden="true">vs</span>':''}<a href="${guideHref(c)}" class="vs-side">${avatar(c)}<strong>${esc(c.title)}</strong><small>${esc(c.kind)}</small></a>`).join('')}</div><p class="lead">${esc(a.summary)}</p><section><h2>What to watch</h2><p>${esc(a.focus)}</p><div class="sides">${a.sides.map(([h,p],k)=>`<div class="side" data-role="${esc(cs[k].tags[0])}"><h3>${esc(h)}</h3><p>${esc(p)}</p></div>`).join('')}</div></section>`;if(a.phases)body+=`<section><h2>How the lane changes</h2><div class="sides phases">${a.phases.map(([h,p])=>`<div class="side" data-role="${esc(cs[0].tags[0])}"><h3>${esc(h)}</h3><p>${esc(p)}</p></div>`).join('')}</div></section>`;if(a.tips)body+=`<section><h2>Quick tips for ${esc(cs[0].title)}</h2><ul class="mu-tips">${a.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`;body+=`<section><h2>Pause and decide</h2><p>${esc(a.scenario)}</p></section>`;}
  body+=`<section class="practice"><h2>Replay exercise</h2><p>${esc(a.drill)}</p>${mode==='champions'?'':'<p>Use a replay where you played either champion, or watch a recorded game of the matchup. Pause just before each exchange and predict who should win it and why, then play it out and compare. Repeat the exercise from the other side: knowing what your opponent wants makes your own choices clearer.</p>'}</section><section><h2>Build the underlying skills</h2><p>${mode==='champions'?'This guide assumes the skills in these lessons. If a step in the teamfight plan feels hard, the matching lesson breaks it down with an example and a practice exercise. Work on one per game rather than all at once.':'Both sides of this matchup rely on the skills in these lessons. Each one breaks a skill down with an example and a practice exercise you can try in your next game.'}</p><div class="guide-links">${a.lessons.map(slug=>{const l=LESSONS.find(l=>l.slug===slug);return l?`<a href="#/lesson/${slug}">${esc(l.title)}</a>`:'';}).join('')}</div></section>`;
  if(mode!=='champions'||MATCHUPS.some(m=>m.champions.includes(a.slug)))body+=`<section><h2>${mode==='champions'?'Related matchups':'Champion pages'}</h2>${guideLinks(mode==='champions'?MATCHUPS.filter(m=>m.champions.includes(a.slug)):CHAMPIONS.filter(c=>a.champions.includes(c.slug)))}</section>`;
  if(mode==='champions'){const i=CHAMPIONS.indexOf(a),pv=CHAMPIONS[i-1],nx=CHAMPIONS[i+1],like=CHAMPIONS.filter(c=>c!==a&&c.kind===a.kind&&c.tags.some(t=>a.tags.includes(t))).slice(0,4);
   body+=`<section><h2>Similar champions</h2><p>Same teamfight style, so the same questions apply.</p><div class="champ-grid compact">${like.map(championCard).join('')}</div></section><nav class="pager" aria-label="Neighbouring champions">${pv?`<a href="${guideHref(pv)}"><small>← Previous</small><strong>${esc(pv.title)}</strong></a>`:'<span></span>'}${nx?`<a href="${guideHref(nx)}"><small>Next →</small><strong>${esc(nx.title)}</strong></a>`:'<span></span>'}</nav>`;}
  const sources=mode==='champions'?[a]:CHAMPIONS.filter(c=>a.champions.includes(c.slug));
  body+=`<section><h2>Sources and scope</h2><p class="note">Champion coverage and ability references use Riot Data Dragon ${esc(CHAMPIONS[0].version)}, cross-checked against Riot’s full champion directory on 5 November 2026 UTC (4 November Pacific). Tactical guidance, diagrams and hypothetical scenarios are editorial interpretations of the kits, not Riot recommendations or win-rate predictions. Check current in-game tooltips for numbers and changes.</p><div class="guide-links">${sources.map(c=>`<a href="${esc(c.riotUrl)}">Riot: ${esc(c.title)}</a><a href="${esc(c.source)}">${esc(c.title)} ability source</a>`).join('')}</div></section>`;
 }else if(detail)body=`<p>This guide is not in the collection.</p><a href="#/${mode}">Browse ${mode}</a>`;
 else body=`<p class="lead">${mode==='champions'?'Choose a champion to connect their kit to practical learning exercises.':'Choose a pair to practise reading the lane from both sides.'}</p><p>${mode==='champions'?'The complete verified roster has '+items.length+' guides, each with playstyle, strengths, weaknesses, a teamfight plan and a replay exercise.':'This starter matchup collection has '+items.length+' guides.'}</p>${guideLinks(items)}`;
 $('#content').innerHTML=`<article class="article"><div class="eyebrow">${mode==='champions'?'Champions / '+CHAMPIONS.length+' guides':'Matchups / Starter collection'}</div>${a&&mode==='champions'?`<div class="title-row">${avatar(a)}<h1 tabindex="-1">${esc(title)}</h1></div>`:`<h1 tabindex="-1">${esc(title)}</h1>`}${body}</article>`;
 document.title=title+' — League.guide';document.body.dataset.view=detail?'article':'list';
 if(a&&!matchesGuide(a,directoryQueries[mode]||''))directoryQueries[mode]='';
 updateIndex();
 $('.browser').scrollTop=state?.ds||0;$('.reader').scrollTop=state?.rs||0;
 if(!initial){if(detail)$('.article h1').focus({preventScroll:true});else $(`[data-index="${mode}"]`).focus({preventScroll:true});}return true;
}
// App initialization follows this script and supplies the shared navigation helpers.
document.addEventListener('DOMContentLoaded',()=>{
 document.querySelector('#content').addEventListener('click',e=>{const b=e.target.closest('[data-jump]');if(!b)return;const t=document.getElementById('cg-'+b.dataset.jump);if(!t)return;t.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});document.querySelectorAll('[data-jump]').forEach(x=>x.setAttribute('aria-current',x===b));});
 document.querySelector('#directory-search').oninput=e=>{directoryQueries[indexMode()]=e.target.value;updateIndex();save();};
 document.querySelector('#directory-reset').onclick=()=>{directoryQueries[indexMode()]='';updateIndex();$('#directory-search').focus();save();};
});
